class Network(enum.Enum):
    """
    A network mode for a client.

    `Tor` always exists, so generated bindings are the same for every build.
    When the runtime is built without Tor, opening a client with `Tor` gives
    `ErrorCode::Unsupported` and `Capabilities::networks` does not list it.
"""
    
    DIRECT = 0
    
    LAN = 1
    
    NEARBY = 2
    
    WAN = 3
    
    RELAY_ONLY = 4
    
    WAN_ONLY = 5
    
    TOR = 6
    


class _UniffiFfiConverterTypeNetwork(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return Network.DIRECT
        if variant == 2:
            return Network.LAN
        if variant == 3:
            return Network.NEARBY
        if variant == 4:
            return Network.WAN
        if variant == 5:
            return Network.RELAY_ONLY
        if variant == 6:
            return Network.WAN_ONLY
        if variant == 7:
            return Network.TOR
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value == Network.DIRECT:
            return
        if value == Network.LAN:
            return
        if value == Network.NEARBY:
            return
        if value == Network.WAN:
            return
        if value == Network.RELAY_ONLY:
            return
        if value == Network.WAN_ONLY:
            return
        if value == Network.TOR:
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value == Network.DIRECT:
            buf.write_i32(1)
        if value == Network.LAN:
            buf.write_i32(2)
        if value == Network.NEARBY:
            buf.write_i32(3)
        if value == Network.WAN:
            buf.write_i32(4)
        if value == Network.RELAY_ONLY:
            buf.write_i32(5)
        if value == Network.WAN_ONLY:
            buf.write_i32(6)
        if value == Network.TOR:
            buf.write_i32(7)



class _UniffiFfiConverterSequenceTypeNetwork(_UniffiConverterRustBuffer):
    @classmethod
    def check_lower(cls, value):
        for item in value:
            _UniffiFfiConverterTypeNetwork.check_lower(item)

    @classmethod
    def write(cls, value, buf):
        items = len(value)
        buf.write_i32(items)
        for item in value:
            _UniffiFfiConverterTypeNetwork.write(item, buf)

    @classmethod
    def read(cls, buf):
        count = buf.read_i32()
        if count < 0:
            raise InternalError("Unexpected negative sequence length")

        return [
            _UniffiFfiConverterTypeNetwork.read(buf) for i in range(count)
        ]






