@dataclass
class Limits:
    """
    Resource limits of one runtime `Context` (ADR step 3). Every session of
    the context counts toward them; two contexts never share them.

    The defaults suit a desktop host and parallel tests. A phone host sets
    lower values, for example `Limits::default().with_max_sessions(8)`.
"""
    def __init__(self, *, max_sessions:int, max_overlay_paths:int):
        self.max_sessions = max_sessions
        self.max_overlay_paths = max_overlay_paths
        
        

    
    def __str__(self):
        return "Limits(max_sessions={}, max_overlay_paths={})".format(self.max_sessions, self.max_overlay_paths)
    def __eq__(self, other):
        if self.max_sessions != other.max_sessions:
            return False
        if self.max_overlay_paths != other.max_overlay_paths:
            return False
        return True

class _UniffiFfiConverterTypeLimits(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        return Limits(
            max_sessions=_UniffiFfiConverterUInt32.read(buf),
            max_overlay_paths=_UniffiFfiConverterUInt32.read(buf),
        )

    @staticmethod
    def check_lower(value):
        _UniffiFfiConverterUInt32.check_lower(value.max_sessions)
        _UniffiFfiConverterUInt32.check_lower(value.max_overlay_paths)

    @staticmethod
    def write(value, buf):
        _UniffiFfiConverterUInt32.write(value.max_sessions, buf)
        _UniffiFfiConverterUInt32.write(value.max_overlay_paths, buf)

@dataclass
class Capabilities:
    """
    What this build and client support (returned by `Client::capabilities`,
    ADR step 6).

    Limits belong to the client's runtime context.
"""
    def __init__(self, *, api_version:int, networks:typing.List[Network], features:typing.List[Feature], limits:Limits):
        self.api_version = api_version
        self.networks = networks
        self.features = features
        self.limits = limits
        
        

    
    def __str__(self):
        return "Capabilities(api_version={}, networks={}, features={}, limits={})".format(self.api_version, self.networks, self.features, self.limits)
    def __eq__(self, other):
        if self.api_version != other.api_version:
            return False
        if self.networks != other.networks:
            return False
        if self.features != other.features:
            return False
        if self.limits != other.limits:
            return False
        return True

class _UniffiFfiConverterTypeCapabilities(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        return Capabilities(
            api_version=_UniffiFfiConverterUInt32.read(buf),
            networks=_UniffiFfiConverterSequenceTypeNetwork.read(buf),
            features=_UniffiFfiConverterSequenceTypeFeature.read(buf),
            limits=_UniffiFfiConverterTypeLimits.read(buf),
        )

    @staticmethod
    def check_lower(value):
        _UniffiFfiConverterUInt32.check_lower(value.api_version)
        _UniffiFfiConverterSequenceTypeNetwork.check_lower(value.networks)
        _UniffiFfiConverterSequenceTypeFeature.check_lower(value.features)
        _UniffiFfiConverterTypeLimits.check_lower(value.limits)

    @staticmethod
    def write(value, buf):
        _UniffiFfiConverterUInt32.write(value.api_version, buf)
        _UniffiFfiConverterSequenceTypeNetwork.write(value.networks, buf)
        _UniffiFfiConverterSequenceTypeFeature.write(value.features, buf)
        _UniffiFfiConverterTypeLimits.write(value.limits, buf)

class _UniffiFfiConverterString:
    @staticmethod
    def check_lower(value):
        if not isinstance(value, str):
            raise TypeError("argument must be str, not {}".format(type(value).__name__))
        return value

    @staticmethod
    def read(buf):
        size = buf.read_i32()
        if size < 0:
            raise InternalError("Unexpected negative string length")
        utf8_bytes = buf.read(size)
        return utf8_bytes.decode("utf-8")

    @staticmethod
    def write(value, buf):
        utf8_bytes = value.encode("utf-8")
        buf.write_i32(len(utf8_bytes))
        buf.write(utf8_bytes)

    @staticmethod
    def lift(buf):
        with buf.consume_with_stream() as stream:
            return stream.read(stream.remaining()).decode("utf-8")

    @staticmethod
    def lower(value):
        with _UniffiRustBuffer.alloc_with_builder() as builder:
            builder.write(value.encode("utf-8"))
            return builder.finalize()

